{"path": "/workspace/target/src/enrich.py", "content": """"Zone / rate-class enrichment for green-taxi serving requests.

Serving requests do not arrive with the tidy dtypes of the offline parquet: an
identifier may show up as ``74``, ``74.0``, ``" 74.0 "`` or as a token that is
not a number at all.  The lookup tables shipped in ``data/`` are authoritative
for how each published identifier resolves:

* Every ``LocationID`` present in ``taxi_zone_lookup.csv`` resolves through its
  own row.  When a row's ``Borough`` or ``service_zone`` is blank, the published
  value falls back to that row's ``Zone`` label.  An identifier still without a
  value after that fallback, or one absent from the table, has no zone and is
  reported as ``UNKNOWN``.
* ``rate_codes.csv`` is the codebook; a missing ``RatecodeID`` is published by
  the TLC as code ``99`` (``unknown_reported`` / ``unspecified``).  A code
  outside the codebook has no rate class and is reported as ``UNKNOWN``.
"""

from __future__ import annotations

import math

import numpy as np
import pandas as pd

UNKNOWN = "UNKNOWN"

ENRICHED_COLUMNS = ["pu_borough", "pu_service_zone", "do_borough",
                    "do_service_zone", "rate_class", "fare_basis"]

# The TLC publishes trips whose rate was not reported with the RatecodeID column
# absent; the codebook records that situation as code 99.
DEFAULT_RATE_CODE = 99

_MISSING_TOKENS = {"", "nan", "none", "null", "na", "n/a", "-", "?"}


def _clean_label(value) -> str | None:
    """Return a non-empty stripped label, or ``None`` when the cell is blank."""
    if value is None:
        return None
    if isinstance(value, float) and math.isnan(value):
        return None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    if text == "" or text.lower() in {"nan", "none", "null"}:
        return None
    return text


def _to_code(value):
    """Coerce a loosely-typed identifier/code to ``int``; ``None`` if impossible."""
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, np.integer)):
        return int(value)
    if isinstance(value, (float, np.floating)):
        if math.isnan(value) or math.isinf(value):
            return None
        if float(value) != int(value):
            return None
        return int(value)
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    if text == "" or text.lower() in _MISSING_TOKENS:
        return None
    try:
        number = float(text)
    except ValueError:
        return None
    if math.isnan(number) or math.isinf(number) or number != int(number):
        return None
    return int(number)


def _zone_maps(zones: pd.DataFrame) -> tuple[dict, dict]:
    """Build ``LocationID -> borough`` / ``-> service zone`` maps with fallback."""
    boroughs: dict[int, str] = {}
    service_zones: dict[int, str] = {}
    for row in zones.itertuples(index=False):
        location = _to_code(getattr(row, "LocationID", None))
        if location is None:
            continue
        zone_label = _clean_label(getattr(row, "Zone", None))
        borough = _clean_label(getattr(row, "Borough", None)) or zone_label
        service = _clean_label(getattr(row, "service_zone", None)) or zone_label
        boroughs[location] = borough if borough is not None else UNKNOWN
        service_zones[location] = service if service is not None else UNKNOWN
    return boroughs, service_zones


def _rate_maps(rates: pd.DataFrame) -> tuple[dict, dict]:
    classes: dict[int, str] = {}
    bases: dict[int, str] = {}
    for row in rates.itertuples(index=False):
        code = _to_code(getattr(row, "code", None))
        if code is None:
            continue
        rate_class = _clean_label(getattr(row, "rate_class", None))
        fare_basis = _clean_label(getattr(row, "fare_basis", None))
        classes[code] = rate_class if rate_class is not None else UNKNOWN
        bases[code] = fare_basis if fare_basis is not None else UNKNOWN
    return classes, bases


def _lookup_series(values: pd.Series, table: dict) -> pd.Series:
    resolved = []
    for value in values.tolist():
        code = _to_code(value)
        if code is None:
            resolved.append(UNKNOWN)
        else:
            resolved.append(table.get(code, UNKNOWN))
    return pd.Series(resolved, index=values.index, dtype="object")


def enrich(trips: pd.DataFrame, zones: pd.DataFrame, rates: pd.DataFrame) -> pd.DataFrame:
    boroughs, service_zones = _zone_maps(zones)
    rate_classes, fare_bases = _rate_maps(rates)

    out = trips.copy()

    pu = trips["PULocationID"] if "PULocationID" in trips.columns else pd.Series(
        [None] * len(trips), index=trips.index)
    do = trips["DOLocationID"] if "DOLocationID" in trips.columns else pd.Series(
        [None] * len(trips), index=trips.index)

    out["pu_borough"] = _lookup_series(pu, boroughs)
    out["pu_service_zone"] = _lookup_series(pu, service_zones)
    out["do_borough"] = _lookup_series(do, boroughs)
    out["do_service_zone"] = _lookup_series(do, service_zones)

    if "RatecodeID" in trips.columns:
        raw_codes = trips["RatecodeID"]
    else:
        raw_codes = pd.Series([None] * len(trips), index=trips.index)

    codes = []
    for value in raw_codes.tolist():
        code = _to_code(value)
        # An absent RatecodeID is published by the TLC as the "not reported"
        # class; a present-but-uninterpretable value has no rate class.
        if code is None:
            code = DEFAULT_RATE_CODE if _clean_label(value) is None else None
        codes.append(code)

    out["rate_class"] = [
        UNKNOWN if code is None else rate_classes.get(code, UNKNOWN) for code in codes]
    out["fare_basis"] = [
        UNKNOWN if code is None else fare_bases.get(code, UNKNOWN) for code in codes]

    for column in ENRICHED_COLUMNS:
        out[column] = out[column].astype(str)
    return out
"}

{"path": "/workspace/target/src/serve.py", "content": "from __future__ import annotations

from pathlib import Path
from typing import Iterable, Mapping

import pandas as pd

from . import enrich, features, model, time_contract

DATA = Path(__file__).resolve().parent.parent / "data"

CONTRACT_COLUMNS = list(features.CONTRACT_COLUMNS)

_REFERENCE: tuple[pd.DataFrame, pd.DataFrame] | None = None


def load_reference() -> tuple[pd.DataFrame, pd.DataFrame]:
    global _REFERENCE
    if _REFERENCE is None:
        zones = pd.read_csv(DATA / "taxi_zone_lookup.csv", dtype=str, keep_default_na=False,
                            na_values=[""])
        rates = pd.read_csv(DATA / "rate_codes.csv", dtype=str, keep_default_na=False,
                            na_values=[""])
        _REFERENCE = (zones, rates)
    zones, rates = _REFERENCE
    return zones.copy(), rates.copy()


def as_frame(records) -> pd.DataFrame:
    """Accept a DataFrame, a mapping of columns, a record, or an iterable of records."""
    if isinstance(records, pd.DataFrame):
        return records
    if isinstance(records, Mapping):
        if any(isinstance(value, (list, tuple, pd.Series)) for value in records.values()):
            return pd.DataFrame(records)
        return pd.DataFrame([dict(records)])
    if isinstance(records, Iterable):
        return pd.DataFrame(list(records))
    raise TypeError(f"unsupported request payload: {type(records)!r}")


def enrich_batch(trips) -> pd.DataFrame:
    zones, rates = load_reference()
    return enrich.enrich(as_frame(trips), zones, rates)


def contract_batch(trips) -> pd.DataFrame:
    """Return the full serving contract (zone, rate and temporal) columns."""
    zones, rates = load_reference()
    return features.contract_frame(as_frame(trips), zones, rates)


def temporal_batch(trips) -> pd.DataFrame:
    frame = as_frame(trips)
    return time_contract.derive(features.pickup_series(frame))


def build_matrix(trips) -> pd.DataFrame:
    zones, rates = load_reference()
    return features.build(as_frame(trips), zones, rates)


def serve_record(record: Mapping) -> dict:
    """Resolve a single serving request into its contract columns."""
    contract = contract_batch([dict(record)])
    return {column: str(contract.iloc[0][column]) for column in CONTRACT_COLUMNS}


def score_batch(estimator, trips) -> pd.Series:
    matrix = build_matrix(trips)
    return pd.Series(estimator.predict(matrix), name="predicted_duration_minutes")
